const serviceIcons = {code:Code2,shield:ShieldCheck,cloud:Cloud,network:Network,data:Database,support:Headset};
function App(){
 const [lang,setLang]=useState('ar'); const [menu,setMenu]=useState(false); const [openFaq,setOpenFaq]=useState(0); const [form,setForm]=useState({name:'',email:'',company:'',message:''}); const [error,setError]=useState('');
 const t=copy[lang], rtl=lang==='ar';
 const go=(id)=>{setMenu(false);document.getElementById(id)?.scrollIntoView({behavior:'smooth'});};
 const submit=(e)=>{e.preventDefault();setError('');if(!form.name.trim()||!form.email.trim()||!form.message.trim()){setError(t.required);return;}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)){setError(t.invalid);return;}const subject=encodeURIComponent(`NEXORA website inquiry — ${form.name}`);const body=encodeURIComponent(`Name: ${form.name}\nEmail: ${form.email}\nCompany: ${form.company}\n\nProject details:\n${form.message}`);window.location.href=`mailto:hello@nexora.tech?subject=${subject}&body=${body}`;};
 return <div className={rtl?'app rtl':'app ltr'} dir={rtl?'rtl':'ltr'}>
  <header className="header"><div className="container nav-wrap"><a className="brand" href="#home" onClick={e=>{e.preventDefault();go('home')}}><span className="brand-mark"><img src="data:image/png;base64," alt=""/></span><span className="brand-name">NEXORA<span>TECHNOLOGY</span></span></a><nav className={menu?'nav open':'nav'}>{t.nav.map((n,i)=><button key={n} onClick={()=>go(['home','services','work','about','contact'][i])} className={i===0?'nav-link active':'nav-link'}>{n}</button>)}<button className="nav-cta" onClick={()=>go('contact')}>{t.primary}<ArrowLeft size={16}/></button></nav><div className="nav-actions"><button className="lang-switch" onClick={()=>setLang(rtl?'en':'ar')} aria-label="Switch language"><Globe2 size={16}/>{rtl?'EN':'عربي'}</button><button className="mobile-toggle" onClick={()=>setMenu(!menu)} aria-label="Toggle menu">{menu?<X/>:<Menu/>}</button></div></div></header>
  <main><section className="hero" id="home"><div className="hero-grid"></div><div className="container hero-layout"><div className="hero-copy"><div className="eyebrow"><span className="eyebrow-dot"></span>{t.badge}</div><h1>{t.titleA}<br/><span>{t.titleB}</span></h1><p className="hero-intro">{t.intro}</p><div className="hero-buttons"><button className="btn btn-primary" onClick={()=>go('contact')}>{t.primary}<ArrowLeft size={18}/></button><button className="btn btn-ghost" onClick={()=>go('services')}>{t.secondary}<ArrowUpLeft size={18}/></button></div><div className="hero-trust"><div className="avatar-stack"><span>N</span><span>X</span><span>+</span></div><span>{t.trusted}</span><div className="trust-stars">★★★★★</div></div></div><div className="hero-visual"><div className="visual-glow"></div><div className="orbit orbit-one"></div><div className="orbit orbit-two"></div><div className="tech-card card-top"><span className="mini-icon"><ShieldCheck size={20}/></span><span><b>{rtl?'أمان موثوق':'Trusted security'}</b><small>{rtl?'حماية من البداية':'Secure by design'}</small></span><span className="status-dot"></span></div><div className="core-visual"><div className="core-ring ring-a"></div><div className="core-ring ring-b"></div><div className="core-logo"><img src="data:image/png;base64," alt="NEXORA network logo"/></div><div className="node node-a"></div><div className="node node-b"></div><div className="node node-c"></div><div className="node node-d"></div><div className="connection connection-a"></div><div className="connection connection-b"></div><div className="connection connection-c"></div></div><div className="tech-card card-bottom"><span className="mini-icon cyan"><Zap size={20}/></span><span><b>{rtl?'أداء أسرع':'Performance boost'}</b><small>{rtl?'مصمّم للتوسّع':'Built to scale'}</small></span><span className="trend">↗ 24%</span></div><div className="floating-tag"><Sparkles size={15}/>{rtl?'حلول ذكية':'Smart solutions'}</div></div></div><div className="container stats-row">{t.stats.map((s,i)=><div className="stat" key={s[1]}><strong>{s[0]}</strong><span>{s[1]}</span></div>)}<div className="stats-note"><span className="note-line"></span>{rtl?'نقيس نجاحنا بنجاحك':'Your success is our measure'}</div></div></section>
  <section className="section services-section" id="services"><div className="container"><div className="section-heading"><div><div className="section-eyebrow">{t.eyebrow}<span></span></div><h2>{t.servicesTitle}<br/><span>{t.servicesTitle2}</span></h2></div><p>{t.servicesIntro}</p></div><div className="services-grid">{t.services.map((s,i)=>{const Icon=serviceIcons[s[2]];return <article className="service-card" key={s[0]}><div className="service-top"><span className="service-icon"><Icon size={23}/></span><span className="service-number">0{i+1}</span></div><h3>{s[0]}</h3><p>{s[1]}</p><button className="card-arrow" aria-label={s[0]} onClick={()=>go('contact')}><ArrowUpLeft size={19}/></button></article>})}</div></div></section>
  <section className="about-section" id="about"><div className="container about-layout"><div className="about-art"><div className="about-art-bg"></div><div className="big-number">N<span>.</span></div><div className="about-badge"><span className="badge-check"><Check size={17}/></span><span><b>{rtl?'شريك موثوق':'A trusted partner'}</b><small>{rtl?'من التخطيط إلى النمو':'From planning to growth'}</small></span></div><div className="art-caption">NEXORA <span>TECHNOLOGY / 01</span></div></div><div className="about-copy"><div className="section-eyebrow">{t.aboutEyebrow}<span></span></div><h2>{t.aboutTitle}<br/><span>{t.aboutTitle2}</span></h2><p>{t.aboutText}</p><div className="check-list">{t.points.map(p=><div key={p}><CircleCheck size={19}/><span>{p}</span></div>)}</div><button className="btn btn-primary" onClick={()=>go('contact')}>{t.aboutCta}<ArrowLeft size={18}/></button></div></div></section>
  <section className="process-section"><div className="container"><div className="section-heading process-heading"><div><div className="section-eyebrow">{t.processEyebrow}<span></span></div><h2>{t.processTitle}<br/><span>{t.processTitle2}</span></h2></div><div className="process-decoration"><span></span><span></span><span></span><span></span><span></span><span></span><span></span></div></div><div className="steps-grid">{t.steps.map((s,i)=><div className="step" key={s[0]}><div className="step-number"><span>0{i+1}</span><div className="step-line"></div></div><h3>{s[0]}</h3><p>{s[1]}</p></div>)}</div></div></section>
  <section className="work-section" id="work"><div className="container"><div className="section-heading"><div><div className="section-eyebrow">{t.workEyebrow}<span></span></div><h2>{t.workTitle}<br/><span>{t.workTitle2}</span></h2></div><p>{t.workIntro}</p></div><div className="projects-grid">{t.projects.map((p,i)=><article className={`project-card project-${i+1}`} key={p[0]}><div className="project-art"><div className="project-grid-lines"></div>{i===0?<div className="browser-art"><div className="browser-bar"><i></i><i></i><i></i></div><div className="browser-content"><div className="browser-sidebar"></div><div className="browser-main"><span></span><span></span><div className="browser-chart"><i></i><i></i><i></i><i></i><i></i></div></div></div></div>:i===1?<div className="cloud-art"><Cloud size={85} strokeWidth={1.2}/><div className="cloud-nodes"><i></i><i></i><i></i><i></i></div></div>:<div className="shield-art"><ShieldCheck size={100} strokeWidth={1.1}/><div className="shield-scan"></div></div>}<span className="project-count">{p[2]}</span></div><div className="project-info"><div><h3>{p[0]}</h3><p>{p[1]}</p></div><button onClick={()=>go('contact')} aria-label={p[0]}><ArrowUpLeft size={20}/></button></div></article>)}</div></div></section>
  <section className="quote-section"><div className="container quote-inner"><div className="quote-mark">“</div><blockquote>{t.quote}</blockquote><div className="quote-by"><span></span>{t.quoteBy}</div><div className="quote-orbit"></div></div></section>
  <section className="faq-section"><div className="container faq-layout"><div><div className="section-eyebrow">{t.faqEyebrow}<span></span></div><h2>{t.faqTitle}</h2><p className="faq-side-text">{rtl?'نحن هنا لمساعدتك في اتخاذ القرار التقني الصحيح.':'We’re here to help you make the right technology decision.'}</p><div className="faq-contact"><MessageCircle size={19}/><span>{rtl?'تحتاج إلى إجابة أخرى؟':'Need another answer?'}</span><button onClick={()=>go('contact')}>{rtl?'تواصل معنا':'Contact us'} <ArrowLeft size={15}/></button></div></div><div className="faq-list">{t.faqs.map((f,i)=><div className={openFaq===i?'faq-item expanded':'faq-item'} key={f[0]}><button className="faq-question" onClick={()=>setOpenFaq(openFaq===i?-1:i)}><span>{f[0]}</span><ChevronDown size={19}/></button>{openFaq===i&&<p className="faq-answer">{f[1]}</p>}</div>)}</div></div></section>
  <section className="contact-section" id="contact"><div className="container"><div className="contact-panel"><div className="contact-copy"><div className="section-eyebrow light">{t.contactEyebrow}<span></span></div><h2>{t.contactTitle}<br/><span>{t.contactTitle2}</span></h2><p>{t.contactText}</p><div className="contact-details"><h3>{t.contactInfo}</h3><a href="mailto:hello@nexora.tech"><span className="detail-icon"><Mail size={18}/></span><span><small>{t.emailLabel}</small><b>hello@nexora.tech</b></span></a><a href="tel:+201000000000"><span className="detail-icon"><Phone size={18}/></span><span><small>{t.phoneLabel}</small><b dir="ltr">+20 100 000 0000</b></span></a><div className="contact-location"><span className="detail-icon"><MapPin size={18}/></span><span><small>{t.locationLabel}</small><b>{t.location}</b></span></div></div></div><form className="contact-form" onSubmit={submit}><div className="form-heading"><span>{rtl?'أخبرنا عن مشروعك':'Tell us about your project'}</span><span className="form-step">01 / 01</span></div><label>{t.name}<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder={rtl?'مثال: أحمد محمد':'e.g. Alex Morgan'} autoComplete="name"/></label><label>{t.email}<input value={form.email} onChange={e=>setForm({...form,email:e.target.value})} placeholder="you@company.com" type="email" autoComplete="email"/></label><label>{t.company}<input value={form.company} onChange={e=>setForm({...form,company:e.target.value})} placeholder={rtl?'اسم الشركة':'Company name'} autoComplete="organization"/></label><label>{t.message}<textarea value={form.message} onChange={e=>setForm({...form,message:e.target.value})} placeholder={rtl?'ما الذي ترغب في بنائه أو تحسينه؟':'What would you like to build or improve?'} rows="4"/></label>{error&&<div className="form-error">{error}</div>}<button className="btn btn-primary submit-btn" type="submit">{t.send}<Send size={17}/></button><p className="form-note"><ShieldCheck size={14}/>{t.formNote}</p></form></div></div></section></main>
  <footer className="footer"><div className="container"><div className="footer-main"><div className="footer-brand"><a className="brand" href="#home" onClick={e=>{e.preventDefault();go('home')}}><span className="brand-mark"><img src="data:image/png;base64," alt=""/></span><span className="brand-name">NEXORA<span>TECHNOLOGY</span></span></a><p>{t.footerText}</p><div className="socials"><a href="https://www.linkedin.com/" aria-label="LinkedIn"><Linkedin size={17}/></a><a href="https://www.instagram.com/" aria-label="Instagram"><Instagram size={17}/></a><a href="https://github.com/" aria-label="GitHub"><Github size={17}/></a></div></div><div className="footer-links"><h4>{t.links}</h4>{t.nav.map((n,i)=><button key={n} onClick={()=>go(['home','services','work','about','contact'][i])}>{n}</button>)}</div><div className="footer-links"><h4>{t.servicesLabel}</h4>{t.services.slice(0,4).map(s=><button key={s[0]} onClick={()=>go('services')}>{s[0]}</button>)}</div><div className="footer-news"><div className="footer-chip"><span></span>{rtl?'مستعدون للخطوة القادمة؟':'Ready for what’s next?'}</div><h3>{rtl?'خلّينا نبني شيئًا مميزًا.':'Let’s build something great.'}</h3><button className="footer-contact" onClick={()=>go('contact')}>{t.primary}<ArrowUpLeft size={18}/></button></div></div><div className="footer-bottom"><span>© {new Date().getFullYear()} NEXORA. {t.rights}</span><div><button onClick={()=>go('contact')}>{t.privacy}</button><button onClick={()=>go('contact')}>{t.terms}</button></div><button className="back-top" onClick={()=>go('home')}>{t.top}<ArrowUpRight size={15}/></button></div></div></footer>
 </div>
}

createRoot(document.getElementById('root')).render(<React.StrictMode><App/></React.StrictMode>);
